import React, { useState, useEffect, useMemo } from 'react';
import { X, Calendar, ArrowRight, Clock } from 'lucide-react';

export default function BookSlotModal({ isOpen, onClose, initialData, onProceed }) {
  const [date, setDate] = useState('2026-10-06');
  const [duration, setDuration] = useState(initialData?.duration || '30 Minutes');
  const [selectedSlot, setSelectedSlot] = useState('');

  // Dynamically generate time slots from 10:00 AM to 10:00 PM based on selected duration
  const availableSlots = useMemo(() => {
    const slots = [];
    const startHour = 10; // 10:00 AM
    const endHour = 22; // 10:00 PM
    const intervalMins = duration === '30 Minutes' ? 30 : 60;

    let currentMins = startHour * 60;
    const endMins = endHour * 60;

    const formatTime = (minutes) => {
      const h = Math.floor(minutes / 60);
      const m = minutes % 60;
      const ampm = h >= 12 ? 'PM' : 'AM';
      const formattedH = h % 12 === 0 ? 12 : h % 12;
      const formattedM = m.toString().padStart(2, '0');
      return `${formattedH}:${formattedM} ${ampm}`;
    };

    while (currentMins + intervalMins <= endMins) {
      const startTime = formatTime(currentMins);
      const endTime = formatTime(currentMins + intervalMins);
      slots.push(`${startTime} - ${endTime}`);
      currentMins += intervalMins; // Move forward by the interval duration
    }

    return slots;
  }, [duration]);

  // Reset selected slot whenever the duration changes to prevent invalid selections
  useEffect(() => {
    setSelectedSlot('');
  }, [duration]);

  if (!isOpen) return null;

  const handleNext = () => {
    if (!selectedSlot) return; // Prevent proceeding without a slot
    
    const price = duration === '30 Minutes' ? 49 : 99;
    onProceed({
      date,
      slot: selectedSlot,
      duration,
      totalSessionPrice: price
    });
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/80 backdrop-blur-sm">
      <div className="bg-slate-900 border border-slate-800 rounded-3xl max-w-md w-full p-6 sm:p-8 space-y-6 relative shadow-2xl">
        <button
          onClick={onClose}
          className="absolute top-6 right-6 text-slate-400 hover:text-white p-1 rounded-lg transition-colors"
        >
          <X className="w-5 h-5" />
        </button>

        <div className="space-y-1">
          <span className="text-xs font-semibold uppercase tracking-wider text-emerald-400">Step 1 of 3</span>
          <h3 className="text-2xl font-bold text-white">Book a Slot</h3>
        </div>

        {/* Radio toggles to pick session duration */}
        <div className="space-y-2">
          <label className="text-xs font-medium text-slate-400 uppercase tracking-wider flex items-center gap-1">
            <Clock className="w-3 h-3" /> Session Duration
          </label>
          <div className="grid grid-cols-2 gap-3">
            <button
              type="button"
              onClick={() => setDuration('30 Minutes')}
              className={`p-3 rounded-xl border text-sm font-semibold transition-all ${
                duration === '30 Minutes'
                  ? 'bg-violet-600/30 border-violet-500 text-white shadow-[0_0_10px_rgba(139,92,246,0.2)]'
                  : 'bg-slate-800 border-slate-700 text-slate-400 hover:border-slate-600 hover:text-slate-300'
              }`}
            >
              30 Mins (₹49)
            </button>
            <button
              type="button"
              onClick={() => setDuration('1 Hour')}
              className={`p-3 rounded-xl border text-sm font-semibold transition-all ${
                duration === '1 Hour'
                  ? 'bg-violet-600/30 border-violet-500 text-white shadow-[0_0_10px_rgba(139,92,246,0.2)]'
                  : 'bg-slate-800 border-slate-700 text-slate-400 hover:border-slate-600 hover:text-slate-300'
              }`}
            >
              1 Hour (₹99)
            </button>
          </div>
        </div>

        {/* Date picker component */}
        <div className="space-y-2">
          <label className="text-xs font-medium text-slate-400 uppercase tracking-wider">Select Date</label>
          <div className="relative">
            <input
              type="date"
              value={date}
              onChange={(e) => setDate(e.target.value)}
              className="w-full bg-slate-800 border border-slate-700 rounded-xl px-4 py-3 text-white text-sm focus:outline-none focus:border-violet-500 focus:ring-1 focus:ring-violet-500 transition-all"
            />
            <Calendar className="w-4 h-4 text-slate-400 absolute right-4 top-3.5 pointer-events-none" />
          </div>
        </div>

        {/* Time slot selection grid with dynamic intervals */}
        <div className="space-y-2">
          <div className="flex justify-between items-end">
            <label className="text-xs font-medium text-slate-400 uppercase tracking-wider">Select Time Slot</label>
            <span className="text-[10px] text-slate-500">10:00 AM - 10:00 PM</span>
          </div>
          
          <div className="grid grid-cols-2 gap-2 max-h-48 overflow-y-auto pr-1 pb-1 scrollbar-thin">
            {availableSlots.map((slot) => (
              <button
                key={slot}
                type="button"
                onClick={() => setSelectedSlot(slot)}
                className={`py-2.5 px-2 rounded-xl text-xs font-medium border transition-all ${
                  selectedSlot === slot
                    ? 'bg-emerald-500/20 border-emerald-400 text-emerald-300 shadow-[0_0_10px_rgba(52,211,153,0.15)]'
                    : 'bg-slate-800/80 border-slate-700 text-slate-300 hover:border-slate-500 hover:bg-slate-800'
                }`}
              >
                {slot}
              </button>
            ))}
          </div>
        </div>

        {/* Continue Button */}
        <button
          onClick={handleNext}
          disabled={!selectedSlot}
          className={`w-full py-3.5 rounded-xl font-bold flex items-center justify-center space-x-2 transition-all duration-300 ${
            selectedSlot
              ? 'bg-gradient-to-r from-violet-600 to-indigo-600 hover:from-violet-500 hover:to-indigo-500 text-white shadow-lg shadow-violet-600/30'
              : 'bg-slate-800 text-slate-500 cursor-not-allowed border border-slate-700'
          }`}
        >
          <span>{selectedSlot ? 'Continue to Student Details' : 'Select a Time Slot'}</span>
          <ArrowRight className="w-4 h-4" />
        </button>
      </div>
    </div>
  );
}
